def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    best = np.zeros(dim)
    best_cost = float('inf')

    for _ in range(budget):
        candidate = np.zeros(dim)
        for i in range(dim):
            if rng.random() < 0.5:
                candidate[i] = clip(rng.uniform(lb, ub))
            else:
                candidate[i] = best[i]

        cost = func(candidate)

        if cost < best_cost:
            best_cost = cost
            best = candidate

    return best

def algorithm(func, dim, lb, ub, budget, rng):
    x_best = -np.inf * np.ones(dim)
    for _ in range(budget):
        x_candidate = x_best + rng.normal(0, 1e-2, size=dim) * (ub - lb)
        candidate_x = np.clip(x_candidate, lb, ub)
        if func(candidate_x) < func(x_best):
            x_best = candidate_x
    return x_best
